import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { router } from 'kea-router'

import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { urls } from 'scenes/urls'

import { mcpGatewayConfigList } from '../generated/api'
import { TeamMCPGatewayConfigApi } from '../generated/api.schemas'

export interface GatewayRouteGuardLogicProps {
    projectId: number
    requiresAdmin: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayRouteGuardLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    receivedFeatureFlags: boolean // featureFlagLogic
    canRender: boolean
    gatewayConfig: TeamMCPGatewayConfigApi | null
    gatewayConfigInitialized: boolean
    gatewayConfigLoading: boolean
    gatewayEnabled: boolean
    gatewayFlagResolved: boolean
    requiresAdmin: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayRouteGuardLogicActions {
    checkAccess: () => {
        value: true
    }
    loadGatewayConfig: () => any
    loadGatewayConfigFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadGatewayConfigSuccess: (
        gatewayConfig: TeamMCPGatewayConfigApi,
        payload?: any
    ) => {
        gatewayConfig: TeamMCPGatewayConfigApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface gatewayRouteGuardLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        requiresAdmin: (requiresAdmin: boolean) => boolean
        gatewayEnabled: (featureFlags: FeatureFlagsSet) => boolean
        gatewayFlagResolved: (featureFlags: FeatureFlagsSet, receivedFeatureFlags: boolean) => boolean
        canRender: (
            gatewayEnabled: boolean,
            requiresAdmin: boolean,
            gatewayConfigInitialized: boolean,
            gatewayConfig: TeamMCPGatewayConfigApi | null
        ) => boolean
    }
}

export type gatewayRouteGuardLogicType = MakeLogicType<
    gatewayRouteGuardLogicValues,
    gatewayRouteGuardLogicActions,
    GatewayRouteGuardLogicProps,
    gatewayRouteGuardLogicMeta
>

export const gatewayRouteGuardLogic = kea<gatewayRouteGuardLogicType>([
    props({} as GatewayRouteGuardLogicProps),
    key((props) => `${props.projectId}:${props.requiresAdmin ? 'admin' : 'member'}`),
    path((key) => ['products', 'mcp_store', 'frontend', 'gateway', 'gatewayRouteGuardLogic', key]),
    connect(() => ({ values: [featureFlagLogic, ['featureFlags', 'receivedFeatureFlags']] })),
    actions({
        checkAccess: true,
    }),
    loaders(({ props }) => ({
        gatewayConfig: [
            null as TeamMCPGatewayConfigApi | null,
            {
                loadGatewayConfig: async () => await mcpGatewayConfigList(String(props.projectId)),
            },
        ],
    })),
    reducers({
        gatewayConfigInitialized: [
            false,
            {
                loadGatewayConfig: () => false,
                loadGatewayConfigSuccess: () => true,
                loadGatewayConfigFailure: () => true,
            },
        ],
    }),
    selectors({
        requiresAdmin: [(_, props) => [props.requiresAdmin], (requiresAdmin: boolean): boolean => requiresAdmin],
        gatewayEnabled: [
            (selectors) => [selectors.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => Boolean(featureFlags[FEATURE_FLAGS.MCP_GATEWAY]),
        ],
        gatewayFlagResolved: [
            (selectors) => [selectors.featureFlags, selectors.receivedFeatureFlags],
            (featureFlags: FeatureFlagsSet, receivedFeatureFlags: boolean): boolean =>
                featureFlags[FEATURE_FLAGS.MCP_GATEWAY] !== undefined || receivedFeatureFlags,
        ],
        canRender: [
            (selectors) => [
                selectors.gatewayEnabled,
                selectors.requiresAdmin,
                selectors.gatewayConfigInitialized,
                selectors.gatewayConfig,
            ],
            (
                gatewayEnabled: boolean,
                requiresAdmin: boolean,
                gatewayConfigInitialized: boolean,
                gatewayConfig: TeamMCPGatewayConfigApi | null
            ): boolean =>
                gatewayEnabled && (!requiresAdmin || (gatewayConfigInitialized && Boolean(gatewayConfig?.is_admin))),
        ],
    }),
    listeners(({ actions, props, values }) => ({
        checkAccess: () => {
            if (!values.gatewayFlagResolved) {
                return
            }
            if (!values.gatewayEnabled) {
                router.actions.replace(urls.settings('mcp-servers'))
                return
            }
            if (!props.requiresAdmin) {
                return
            }
            if (values.gatewayConfigInitialized) {
                if (!values.gatewayConfig?.is_admin) {
                    router.actions.replace(urls.mcpGateway())
                }
                return
            }
            if (!values.gatewayConfigLoading) {
                actions.loadGatewayConfig()
            }
        },
        loadGatewayConfigSuccess: ({ gatewayConfig }) => {
            if (!gatewayConfig.is_admin) {
                router.actions.replace(urls.mcpGateway())
            }
        },
        loadGatewayConfigFailure: () => {
            router.actions.replace(urls.mcpGateway())
        },
        [featureFlagLogic.actionTypes.setFeatureFlags]: () => {
            actions.checkAccess()
        },
    })),
    afterMount(({ actions }) => {
        actions.checkAccess()
    }),
])
